<?php
declare(strict_types=1);
use MiniErp\Services\PlatformTenantUserData;
require_once __DIR__ . '/_tenant_users.php';require_once __DIR__ . '/../../src/Services/PlatformTenantUserData.php';
[$identity,$tenant,$service,$administrativeContext]=requireTenantUserContext();$tenantId=$administrativeContext->getSelectedTenantId();$userId=filter_input(INPUT_GET,'user_id',FILTER_VALIDATE_INT)?:0;try{$user=$service->find($administrativeContext,$userId);}catch(DomainException $exception){http_response_code(404);echo platformEscape($exception->getMessage());exit;}$values=$user;$error='';
if(($_SERVER['REQUEST_METHOD']??'GET')==='POST'){foreach(['nome','email','role','status'] as $field)if(isset($_POST[$field])&&is_scalar($_POST[$field]))$values[$field]=(string)$_POST[$field];try{requirePlatformUserCsrf();$service->update($administrativeContext,$userId,PlatformTenantUserData::fromArray($_POST));header('Location: /plataforma/empresa-usuarios.php?id='.$tenantId.'&updated=1');exit;}catch(DomainException|InvalidArgumentException $exception){$error=$exception->getMessage();}}
renderPlatformStart($identity,'Editar usuário','Empresas → '.($tenant['nome_fantasia']??'').' → Usuários → Editar');?>
<section class="panel"><p class="eyebrow">Tenant #<?= $tenantId ?></p><h1>Editar usuário</h1><?php if($error!==''):?><p class="message error" role="alert"><?= platformEscape($error) ?></p><?php endif;?><form method="post"><input type="hidden" name="csrf_token" value="<?= platformEscape($_SESSION['platform_user_csrf']) ?>"><div class="detail-grid"><label class="detail">Nome<input name="nome" maxlength="150" required value="<?= platformEscape($values['nome']) ?>"></label><label class="detail">E-mail<input type="email" name="email" maxlength="150" required value="<?= platformEscape($values['email']) ?>"></label><label class="detail">Perfil<select name="role"><option value="user"<?= $values['role']==='user'?' selected':'' ?>>Usuário</option><option value="admin"<?= $values['role']==='admin'?' selected':'' ?>>Administrador da empresa</option></select></label><label class="detail">Status<select name="status"><option value="ativo"<?= $values['status']==='ativo'?' selected':'' ?>>Ativo</option><option value="inativo"<?= $values['status']==='inativo'?' selected':'' ?>>Inativo</option></select></label></div><div class="form-actions"><button class="btn" type="submit">Salvar alterações</button><a class="btn secondary" href="/plataforma/empresa-usuarios.php?id=<?= $tenantId ?>">Cancelar</a></div></form></section><?php renderPlatformEnd(); ?>
